/**
 * ANATHEOS G2b — deterministic, invented DICOM Part 10 fixtures.
 *
 * Every UID and pixel is manufactured exclusively for tests. No clinical
 * image, patient metadata, DICOM sample download or network access.
 * Deliberately not a substitute for conformance test suites or 3D Slicer.
 */
const encoder = new TextEncoder();
const EXPLICIT = "1.2.840.10008.1.2.1";
const IMPLICIT = "1.2.840.10008.1.2";
const JPEG = "1.2.840.10008.1.2.4.50";
const CT = "1.2.840.10008.5.1.4.1.1.2";
const IMPLEMENTATION = "2.25.998800001";
const STUDY = "2.25.998800002";
const LONG_VR = new Set(["OB", "OD", "OF", "OL", "OV", "OW", "SQ", "UC", "UR", "UT", "UN"]);
const u16 = (value) => [value & 255, (value >>> 8) & 255];
const u32 = (value) => [...u16(value & 65535), ...u16(value >>> 16)];

function bytesOf(vr, value) {
  if (Array.isArray(value) || value instanceof Uint8Array) return [...value];
  const data = [...encoder.encode(String(value))];
  if (data.length % 2 !== 0) data.push(vr === "UI" ? 0 : 32);
  return data;
}

function element(group, id, vr, value, explicit = true) {
  const bytes = bytesOf(vr, value);
  if (!explicit) return [...u16(group), ...u16(id), ...u32(bytes.length), ...bytes];
  return [
    ...u16(group), ...u16(id), ...encoder.encode(vr),
    ...(LONG_VR.has(vr) ? [0, 0, ...u32(bytes.length)] : u16(bytes.length)),
    ...bytes,
  ];
}

const ds = (items) => items.map((value) => String(value)).join("\\");
const syntheticUid = (scenario, index) => "2.25.9988" + String(scenario).padStart(4, "0") + String(index).padStart(4, "0");
const makePixels = (rows, columns, layer) =>
  Array.from({ length: rows * columns }, (_, index) =>
    u16((layer * 100 + Math.floor(index / columns) * 10 + index % columns) & 65535)).flat();

/**
 * Explicit or implicit VR Little Endian. Unsupported transfer syntax is
 * deliberately a sentinel only: pixel bytes are not a JPEG codestream.
 */
export function makeSyntheticDicom({
  scenario = 1, layer = 0, rows = 3, columns = 4,
  seriesUid = syntheticUid(scenario, 0), studyUid = STUDY,
  orientation = [1, 0, 0, 0, 1, 0], position = [10, 20, 30],
  pixelSpacing = [2, 3], syntax = EXPLICIT, frames = 1,
  pixels = null, monochrome = "MONOCHROME2",
} = {}) {
  const sopUid = syntheticUid(scenario, layer + 1);
  const metaFields = [
    element(0x0002, 0x0001, "OB", [0, 1]),
    element(0x0002, 0x0002, "UI", CT),
    element(0x0002, 0x0003, "UI", sopUid),
    element(0x0002, 0x0010, "UI", syntax),
    element(0x0002, 0x0012, "UI", IMPLEMENTATION),
  ].flat();
  const meta = [
    ...element(0x0002, 0x0000, "UL", u32(metaFields.length)),
    ...metaFields,
  ];
  const explicit = syntax !== IMPLICIT;
  const fields = [
    element(0x0008, 0x0016, "UI", CT, explicit),
    element(0x0008, 0x0018, "UI", sopUid, explicit),
    element(0x0008, 0x0060, "CS", "CT", explicit),
    element(0x0020, 0x000d, "UI", studyUid, explicit),
    element(0x0020, 0x000e, "UI", seriesUid, explicit),
    element(0x0020, 0x0032, "DS", ds(position), explicit),
    element(0x0020, 0x0037, "DS", ds(orientation), explicit),
    element(0x0028, 0x0002, "US", u16(1), explicit),
    element(0x0028, 0x0004, "CS", monochrome, explicit),
    ...(frames > 1 ? [element(0x0028, 0x0008, "IS", String(frames), explicit)] : []),
    element(0x0028, 0x0010, "US", u16(rows), explicit),
    element(0x0028, 0x0011, "US", u16(columns), explicit),
    element(0x0028, 0x0030, "DS", ds(pixelSpacing), explicit),
    element(0x0028, 0x0100, "US", u16(16), explicit),
    element(0x0028, 0x0101, "US", u16(16), explicit),
    element(0x0028, 0x0102, "US", u16(15), explicit),
    element(0x0028, 0x0103, "US", u16(0), explicit),
    element(0x0028, 0x1052, "DS", "-1000", explicit),
    element(0x0028, 0x1053, "DS", "1", explicit),
    element(0x0028, 0x1050, "DS", "40", explicit),
    element(0x0028, 0x1051, "DS", "400", explicit),
    element(0x7fe0, 0x0010, "OW", pixels ?? makePixels(rows, columns, layer), explicit),
  ].flat();
  const preamble = new Uint8Array(128);
  return Uint8Array.from([...preamble, ...encoder.encode("DICM"), ...meta, ...fields]);
}

/** Scene definitions are constant; not mined from scans or generated by AI. */
export const corpusCases = Object.freeze({
  axialAnisotropic: {
    caseId: "axial-anisotropic",
    expected: "accept",
    point: { voxel: [2, 1, 2], lpsMm: [16, 22, 40], toleranceMm: 1e-8 },
    slices: [2, 0, 1].map((layer) => makeSyntheticDicom({
      scenario: 11, layer, position: [10, 20, 30 + 5 * layer], pixelSpacing: [2, 3],
    })),
  },
  reversedNormal: {
    caseId: "reversed-normal",
    expected: "accept",
    point: { voxel: [1, 2, 1], lpsMm: [7, 24, 25], toleranceMm: 1e-8 },
    slices: [2, 0, 1].map((layer) => makeSyntheticDicom({
      scenario: 12, layer, orientation: [-1, 0, 0, 0, 1, 0],
      position: [10, 20, 30 - 5 * layer], pixelSpacing: [2, 3],
    })),
  },
  oblique: {
    caseId: "oblique",
    expected: "accept-original-only",
    point: { voxel: [2, 1, 2], lpsMm: [13.82842712476, 18.65685424952, 25], toleranceMm: 1e-6 },
    slices: [2, 0, 1].map((layer) => makeSyntheticDicom({
      scenario: 13, layer, orientation: [0.70710678119, 0.70710678119, 0, -0.70710678119, 0.70710678119, 0],
      position: [11, 13, 17 + 4 * layer], pixelSpacing: [2, 3],
    })),
  },
  irregularGap: {
    caseId: "irregular-gap",
    expected: "reject-volume",
    slices: [0, 1, 3].map((z, layer) =>
      makeSyntheticDicom({ scenario: 14, layer, position: [10, 20, 30 + z] })),
  },
  gantryTilt: {
    caseId: "gantry-tilt",
    expected: "reject-volume",
    slices: [0, 1, 2].map((layer) =>
      makeSyntheticDicom({ scenario: 15, layer, position: [10 + 0.5 * layer, 20, 30 + layer] })),
  },
  twoSeries: {
    caseId: "two-series",
    expected: "reject-mixed-volume",
    slices: [
      makeSyntheticDicom({ scenario: 16, layer: 0, seriesUid: syntheticUid(16, 0) }),
      makeSyntheticDicom({ scenario: 17, layer: 0, seriesUid: syntheticUid(17, 0) }),
    ],
  },
  implicitLE: {
    caseId: "implicit-le",
    expected: "accept",
    slices: [0, 1].map((layer) =>
      makeSyntheticDicom({ scenario: 18, layer, syntax: IMPLICIT, position: [10, 20, 30 + layer] })),
  },
  jpegMarker: {
    caseId: "jpeg-transfer-syntax-sentinel",
    expected: "reject-decode",
    slices: [makeSyntheticDicom({ scenario: 19, syntax: JPEG })],
  },
  multiFrame: {
    caseId: "multiframe-unsupported",
    expected: "reject-decode",
    slices: [makeSyntheticDicom({ scenario: 20, frames: 2 })],
  },
});

/**
 * Independent DICOM PS3.3 C.7.6.2 voxel-centre equation for test reference:
 * LPS = IPP + column*PixelSpacing[1]*IOP[0:3]
 *           + row*PixelSpacing[0]*IOP[3:6].
 * Each slice uses its own IPP; no interpolation is implied.
 */
export function expectedVoxelCentreLps(slice, column, row) {
  return [0, 1, 2].map((axis) =>
    slice.imagePosition[axis] +
    column * slice.pixelSpacing[1] * slice.rowDirection[axis] +
    row * slice.pixelSpacing[0] * slice.columnDirection[axis]);
}
